basicCode.vanilla:
import { createToolGroup } from '@/components/ui/tool-group';

createToolGroup({
  calls: chamadas,
  labels: rotulos,
  onOpenChange: (aberto) => registrar(aberto),
});

basicCode.react:
import { ToolGroup } from "@/components/ui/tool-group";

<ToolGroup
  calls={chamadas}
  labels={rotulos}
  onOpenChange={(aberto) => registrar(aberto)}
/>

withLabelsCode.web:
// O título é FUNÇÃO porque plural é decisão de idioma: um componente que
// escolhesse entre singular e plural escolheria por cinco idiomas de uma vez.
//
// Os dois mapas têm as mesmas quatro chaves de propósito. O de cima fala do
// CONJUNTO, o de baixo fala de cada linha.
const rotulos = {
  title: (quantas) => (quantas === 1 ? '1 ferramenta' : `${quantas} ferramentas`),
  summary: {
    pending: 'Espera por você',
    running: 'Em curso',
    done: 'Concluído',
    failed: 'Algo falhou',
  },
  call: {
    pending: 'Esperando você',
    running: 'Em curso',
    done: 'Concluída',
    failed: 'Falhou',
  },
};

extensibilityCode.web:
// O QUE O RESUMO DIZ sai do vocabulário compartilhado, e não de um `if` da
// tela: a ordem de precedência é a mesma nas cinco stacks.
summarizeToolCalls(chamadas).state;
// 'failed'  → algo falhou, e o resumo diz isso com a caixa fechada
// 'pending' → algo espera por uma pessoa
// 'running' → o grupo ainda não terminou
// 'done'    → tudo terminou bem

// E a chamada que espera por uma PESSOA sai do grupo ANTES de entrar nele.
// Quem separa é quem consome: um componente que filtrasse sozinho apagaria da
// tela um dado que recebeu.
const { grouped, waiting } = splitWaitingCalls(chamadas);

customizationCode.web:
.nds-tool-group {
  max-inline-size: 40rem;
}

/* A seta é REFORÇO, e não a informação: quem carrega o estado do conjunto é a
   palavra na etiqueta do resumo. Mexer nela não muda o que chega a quem ouve. */
.nds-tool-group[open] .nds-tool-group-icon {
  transform: rotate(90deg) scale(1.15);
}

